package io.github.jesterportfolio.hearth.quest;

import io.github.jesterportfolio.hearth.phone.*;
import io.github.jesterportfolio.hearth.persistence.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class QuestFollowupsTest {
    QuestJournal.View view(QuestStore.Phase phase,String status){return PhoneCompletionTest.view(phase,phase==QuestStore.Phase.NOT_ACCEPTED?-1:3,4,status,false);}
    @Test void failedRecordOffersRetryWhilePendingCompletedRecordOffersClaim(){var c=QuestNavigationTest.catalog();var failed=view(QuestStore.Phase.FAILED,"NONE");assertTrue(QuestFollowups.visible(failed,"active"));assertEquals(PhoneCompletion.Operation.RETRY,QuestFollowups.choices(c,failed,"active").getFirst().operation());var reward=view(QuestStore.Phase.COMPLETED,"PENDING");assertTrue(QuestFollowups.visible(reward,"active"));assertEquals(PhoneCompletion.Operation.CLAIM,QuestFollowups.choices(c,reward,"active").getFirst().operation());}
    @Test void noRewardIsInventedForCompletedSkippedOrUnregisteredStates(){for(var phase:List.of(QuestStore.Phase.COMPLETED,QuestStore.Phase.SKIPPED))for(String status:List.of("NONE","UNREGISTERED","GRANTED","POLICY_PENDING","CONFIG_MISMATCH")){var v=view(phase,status);assertFalse(QuestFollowups.visible(v,"active"));assertTrue(QuestFollowups.choices(QuestNavigationTest.catalog(),v,"active").isEmpty());}assertFalse(QuestFollowups.visible(view(QuestStore.Phase.NOT_ACCEPTED,"NONE"),"active"));}
    @Test void blockedUnknownAndOtherPersonalStateHaveNoFollowupActions(){var v=view(QuestStore.Phase.FAILED,"NONE");var x=v.exploration();var blocked=new io.github.jesterportfolio.hearth.exploration.ExplorationView(x.registered(),x.regions(),x.places(),x.facts(),x.events(),x.members(),x.story(),x.conditions(),x.nextGoal(),Set.of("active"),x.branches());var hidden=new QuestJournal.View(v.states(),v.journal(),blocked,v.completion());assertFalse(QuestFollowups.visible(hidden,"active"));assertTrue(QuestFollowups.choices(QuestNavigationTest.catalog(),hidden,"active").isEmpty());assertTrue(QuestFollowups.choices(QuestNavigationTest.catalog(),v,"unknown").isEmpty());assertFalse(QuestFollowups.visible(view(QuestStore.Phase.ACTIVE,"NONE"),"unaccepted"));}
    @Test void confirmationBindsSavedRevisionAndCompletionEpoch(){var c=QuestNavigationTest.catalog();var v=view(QuestStore.Phase.COMPLETED,"PENDING");String original=v.toString();var choice=QuestFollowups.choices(c,v,"active").getFirst();PhoneCompletion.require(c,v,choice);assertEquals(original,v.toString());assertThrows(RuntimeException.class,()->PhoneCompletion.require(c,PhoneCompletionTest.view(QuestStore.Phase.COMPLETED,3,5,"PENDING",false),choice));assertThrows(RuntimeException.class,()->PhoneCompletion.require(c,view(QuestStore.Phase.COMPLETED,"GRANTED"),choice));}
    @Test void facilityShowsRetryAndRewardButPreservesSourceLinkAndEpoch(){var c=FacilityObjectivesTest.catalog();var base=FacilityObjectivesTest.view(FacilityObjectivesTest.row(QuestStore.Phase.FAILED,3,0));var retry=FacilityObjectives.gathering(c,base,PreparationGuideTest.gathering(),Set.of("survey_marker"),List.of());assertEquals(FacilityObjectives.Kind.RETRY,retry.rows().getFirst().kind());var completed=FacilityObjectivesTest.view(FacilityObjectivesTest.row(QuestStore.Phase.COMPLETED,4,1));var pending=new QuestJournal.View(completed.states(),completed.journal(),completed.exploration(),new QuestCompletionView(true,7,Map.of("survey_marker",new QuestCompletionView.Reward("PENDING","지급 대기",true)),List.of()));var reward=FacilityObjectives.gathering(c,pending,PreparationGuideTest.gathering(),Set.of("survey_marker"),List.of());assertEquals(FacilityObjectives.Kind.REWARD,reward.rows().getFirst().kind());assertEquals(7,reward.completionEpoch());assertThrows(IllegalStateException.class,()->FacilityObjectives.require(reward,retry));}
    @Test void craftingFollowupsNeverOfferRecraftOrAllocateMaterials(){var v=new CraftingOrdersTest().view(new QuestStore.Saved(QuestStore.Phase.FAILED,3,0),new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));var board=io.github.jesterportfolio.hearth.crafting.CraftingOrders.build(CraftingQuestTest.catalog(true),CraftingQuestTest.recipes(),"bench",v);assertNull(board.orders().getFirst().recipe());assertTrue(board.page(1).selections().isEmpty());}
    @Test void craftingRewardRowDisappearsAfterGrantAndInvalidatesOldPage(){var v=new CraftingOrdersTest().view(new QuestStore.Saved(QuestStore.Phase.COMPLETED,4,1),new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));var c=CraftingQuestTest.catalog(true);var content=CraftingQuestTest.recipes();var pending=new QuestJournal.View(v.states(),v.journal(),v.exploration(),new QuestCompletionView(true,5,Map.of("survey_marker",new QuestCompletionView.Reward("PENDING","지급 대기",true)),List.of()));var shown=io.github.jesterportfolio.hearth.crafting.CraftingOrders.build(c,content,"bench",pending);assertEquals(1,shown.orders().size());assertNull(shown.orders().getFirst().recipe());assertTrue(shown.page(1).selections().isEmpty());var paid=new QuestJournal.View(v.states(),v.journal(),v.exploration(),new QuestCompletionView(true,6,Map.of("survey_marker",new QuestCompletionView.Reward("GRANTED","지급 완료",false)),List.of()));var fresh=io.github.jesterportfolio.hearth.crafting.CraftingOrders.build(c,content,"bench",paid);assertTrue(fresh.orders().isEmpty());assertThrows(IllegalStateException.class,()->io.github.jesterportfolio.hearth.crafting.CraftingOrders.require(fresh,shown));}
    @Test void warningsAndLabelsDescribeExistingOperationOnly(){for(var op:PhoneCompletion.Operation.values()){var choice=new PhoneCompletion.Choice(op,"active","의뢰",3,1);assertFalse(PhoneCompletion.warning(op).isBlank());assertTrue(QuestFollowups.label(choice).contains("확인"));}assertTrue(PhoneCompletion.warning(PhoneCompletion.Operation.SKIP).contains("보상 정책은 미정"));}
}
